"""Scene outliner dock widget for the 3D viewport.

Lists all scene meshes in a tree view with visibility toggles, selection
synchronisation, triangle counts, and color swatches. Designed to dock on
the left or right side of the QMainWindow.

Usage::

    outliner = OutlinerWidget(main_window)
    main_window.addDockWidget(Qt.LeftDockWidgetArea, outliner)

    # Refresh when objects change
    outliner.refresh(selection_manager.objects)

    # React to user interaction
    outliner.object_selected.connect(viewport.select_by_id)
    outliner.object_visibility_changed.connect(viewport.set_visibility)
    outliner.object_renamed.connect(viewport.rename_object)

    # Toggle with O key
    outliner.setVisible(not outliner.isVisible())

The viewport's ``_draw_scene`` should check
``outliner.model.is_visible(obj_id)`` before drawing each mesh.
"""

from __future__ import annotations

from PySide6.QtCore import Qt, Signal
from PySide6.QtGui import QBrush, QColor, QFont, QIcon, QPixmap
from PySide6.QtWidgets import (
    QDockWidget,
    QHeaderView,
    QTreeWidget,
    QTreeWidgetItem,
    QWidget,
)


# ---------------------------------------------------------------------------
# Dark theme stylesheet
# ---------------------------------------------------------------------------

_DARK_STYLESHEET = """
QDockWidget {
    color: #cccccc;
    font-family: Consolas, monospace;
    font-size: 12px;
    titlebar-close-icon: none;
}
QDockWidget::title {
    background: #1e1e1e;
    color: #cccccc;
    padding: 6px;
}
QTreeWidget {
    background-color: #2b2b2b;
    alternate-background-color: #313131;
    color: #cccccc;
    border: none;
    font-family: Consolas, monospace;
    font-size: 12px;
    outline: 0;
}
QTreeWidget::item {
    height: 24px;
    padding: 2px 4px;
}
QTreeWidget::item:selected {
    background-color: #3d6fa5;
    color: #ffffff;
}
QTreeWidget::item:hover {
    background-color: #353535;
}
QTreeWidget::item:selected:hover {
    background-color: #4a80b8;
}
QHeaderView::section {
    background-color: #1e1e1e;
    color: #999999;
    border: none;
    border-right: 1px solid #3a3a3a;
    padding: 4px 6px;
    font-family: Consolas, monospace;
    font-size: 11px;
}
QTreeWidget::indicator {
    width: 14px;
    height: 14px;
}
QTreeWidget::indicator:checked {
    background-color: #3d6fa5;
    border: 1px solid #5a8fbf;
    border-radius: 2px;
}
QTreeWidget::indicator:unchecked {
    background-color: #3a3a3a;
    border: 1px solid #555555;
    border-radius: 2px;
}
"""

# Column indices
_COL_VISIBILITY = 0
_COL_NAME = 1
_COL_TRIANGLES = 2


# ---------------------------------------------------------------------------
# OutlinerModel -- visibility state tracker
# ---------------------------------------------------------------------------

class OutlinerModel:
    """Tracks per-object visibility state for the outliner.

    The viewport reads ``is_visible`` / ``hidden_object_ids`` each frame
    to decide which meshes to skip during drawing.
    """

    def __init__(self) -> None:
        self._visibility: dict[int, bool] = {}

    def set_visible(self, object_id: int, visible: bool) -> None:
        """Set the visibility of a single object."""
        self._visibility[object_id] = visible

    def is_visible(self, object_id: int) -> bool:
        """Return whether *object_id* is visible.  Defaults to True."""
        return self._visibility.get(object_id, True)

    @property
    def hidden_object_ids(self) -> set[int]:
        """Return the set of object IDs that are currently hidden."""
        return {oid for oid, vis in self._visibility.items() if not vis}

    def clear(self) -> None:
        """Reset all visibility state."""
        self._visibility.clear()


# ---------------------------------------------------------------------------
# Color swatch helper
# ---------------------------------------------------------------------------

def _make_color_swatch(r: float, g: float, b: float, size: int = 16) -> QIcon:
    """Create a small solid-color icon from normalised (0-1) RGB floats."""
    pixmap = QPixmap(size, size)
    pixmap.fill(QColor(
        int(min(max(r, 0.0), 1.0) * 255),
        int(min(max(g, 0.0), 1.0) * 255),
        int(min(max(b, 0.0), 1.0) * 255),
    ))
    return QIcon(pixmap)


# ---------------------------------------------------------------------------
# OutlinerWidget
# ---------------------------------------------------------------------------

class OutlinerWidget(QDockWidget):
    """Dock widget listing all scene objects with visibility and selection.

    Signals
    -------
    object_selected(int)
        Emitted when the user clicks a row. Payload is the object ID.
    object_visibility_changed(int, bool)
        Emitted when a visibility checkbox is toggled. Payload is
        (object_id, new_visible_state).
    object_renamed(int, str)
        Emitted when the user finishes renaming via double-click.
    """

    object_selected = Signal(int)
    object_visibility_changed = Signal(int, bool)
    object_renamed = Signal(int, str)

    def __init__(self, parent: QWidget | None = None) -> None:
        super().__init__("Outliner", parent)

        self.setAllowedAreas(Qt.LeftDockWidgetArea | Qt.RightDockWidgetArea)
        self.setFeatures(
            QDockWidget.DockWidgetMovable
            | QDockWidget.DockWidgetFloatable
            | QDockWidget.DockWidgetClosable
        )

        # Internal visibility model
        self.model = OutlinerModel()

        # Tree widget
        self._tree = QTreeWidget()
        self._tree.setColumnCount(3)
        self._tree.setHeaderLabels(["", "Name", "Tris"])
        self._tree.setAlternatingRowColors(True)
        self._tree.setRootIsDecorated(False)
        self._tree.setSelectionMode(QTreeWidget.SingleSelection)
        self._tree.setIndentation(0)
        self._tree.setFont(QFont("Consolas", 12))

        # Column sizing
        header = self._tree.header()
        header.setMinimumSectionSize(30)
        header.resizeSection(_COL_VISIBILITY, 30)
        header.resizeSection(_COL_TRIANGLES, 80)
        header.setStretchLastSection(False)
        header.setSectionResizeMode(_COL_VISIBILITY, QHeaderView.Fixed)
        header.setSectionResizeMode(_COL_NAME, QHeaderView.Stretch)
        header.setSectionResizeMode(_COL_TRIANGLES, QHeaderView.Fixed)

        self.setWidget(self._tree)
        self.setStyleSheet(_DARK_STYLESHEET)
        self.setMinimumWidth(200)

        # Mapping from object_id -> QTreeWidgetItem for fast lookup
        self._item_map: dict[int, QTreeWidgetItem] = {}

        # Guard flag to suppress signals during programmatic updates
        self._updating = False

        # Connections
        self._tree.itemClicked.connect(self._on_item_clicked)
        self._tree.itemChanged.connect(self._on_item_changed)
        self._tree.itemDoubleClicked.connect(self._on_item_double_clicked)

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def refresh(self, objects: list) -> None:
        """Rebuild the tree from a list of SceneObject instances.

        Each object is expected to have ``id``, ``name``, ``index_count``,
        and ``color`` attributes (matching :class:`selection.SceneObject`).
        """
        self._updating = True
        try:
            self._tree.clear()
            self._item_map.clear()

            for obj in objects:
                item = QTreeWidgetItem()

                # Visibility checkbox (column 0)
                visible = self.model.is_visible(obj.id)
                item.setCheckState(_COL_VISIBILITY, Qt.Checked if visible else Qt.Unchecked)

                # Name with color swatch icon (column 1)
                item.setText(_COL_NAME, obj.name)
                item.setIcon(_COL_NAME, _make_color_swatch(*obj.color[:3]))
                item.setFlags(
                    item.flags()
                    | Qt.ItemIsEditable
                    | Qt.ItemIsSelectable
                    | Qt.ItemIsEnabled
                    | Qt.ItemIsUserCheckable
                )

                # Triangle count (column 2) -- right-aligned
                tri_count = obj.index_count // 3
                item.setText(_COL_TRIANGLES, f"{tri_count:,}")
                item.setTextAlignment(_COL_TRIANGLES, Qt.AlignRight | Qt.AlignVCenter)

                # Store object ID in the item
                item.setData(_COL_NAME, Qt.UserRole, obj.id)

                self._tree.addTopLevelItem(item)
                self._item_map[obj.id] = item

                # Ensure model tracks newly registered objects
                if obj.id not in self.model._visibility:
                    self.model.set_visible(obj.id, True)
        finally:
            self._updating = False

    def set_selection(self, object_id: int | None) -> None:
        """Highlight the row matching *object_id*, or clear selection."""
        self._updating = True
        try:
            self._tree.clearSelection()
            if object_id is not None and object_id in self._item_map:
                item = self._item_map[object_id]
                item.setSelected(True)
                self._tree.scrollToItem(item)
        finally:
            self._updating = False

    def set_visibility(self, object_id: int, visible: bool) -> None:
        """Update the checkbox for *object_id* without emitting a signal."""
        self.model.set_visible(object_id, visible)
        if object_id in self._item_map:
            self._updating = True
            try:
                item = self._item_map[object_id]
                item.setCheckState(
                    _COL_VISIBILITY, Qt.Checked if visible else Qt.Unchecked,
                )
            finally:
                self._updating = False

    # ------------------------------------------------------------------
    # Slots
    # ------------------------------------------------------------------

    def _on_item_clicked(self, item: QTreeWidgetItem, column: int) -> None:
        """Handle row click -- emit selection signal."""
        if self._updating:
            return
        object_id = item.data(_COL_NAME, Qt.UserRole)
        if object_id is not None:
            self.object_selected.emit(object_id)

    def _on_item_changed(self, item: QTreeWidgetItem, column: int) -> None:
        """Handle checkbox toggle or inline rename."""
        if self._updating:
            return
        object_id = item.data(_COL_NAME, Qt.UserRole)
        if object_id is None:
            return

        if column == _COL_VISIBILITY:
            visible = item.checkState(_COL_VISIBILITY) == Qt.Checked
            self.model.set_visible(object_id, visible)
            self.object_visibility_changed.emit(object_id, visible)
        elif column == _COL_NAME:
            new_name = item.text(_COL_NAME)
            self.object_renamed.emit(object_id, new_name)

    def _on_item_double_clicked(self, item: QTreeWidgetItem, column: int) -> None:
        """Start inline editing when the Name column is double-clicked."""
        if column == _COL_NAME:
            self._tree.editItem(item, _COL_NAME)
